echo '### 8787 ЩО ЦЕ'; systemctl cat finrep-trigger.service 2>/dev/null | grep -E 'ExecStart|WorkingDirectory'; echo '### ВІДКРИТІ ЗЄДНАННЯ (зовнішні адреси)'; ss -tn state established 2>/dev/null | awk 'NR==1 || $3 ~ /:8080$|:8787$|:8788$/ || $4 ~ /:8080$|:8787$|:8788$/' | head -15; echo '### N8N — чи згадують воркфлоу базу'; python3 -c 'import json,re,urllib.request
t=open("/root/Iryna_Karmazina/.env").read()
env=dict(re.findall(r"^(\w+)=(.*)$",t,re.M))
K=env.get("N8N_API_KEY","").strip().strip(chr(34)).strip(chr(39))
if not K:
    print("N8N_API_KEY у .env немає"); raise SystemExit
B="https://irynakarmazina.app.n8n.cloud/api/v1/"
def get(u):
    r=urllib.request.Request(u,headers={"X-N8N-API-KEY":K})
    return json.loads(urllib.request.urlopen(r,timeout=25).read())
try:
    d=get(B+"workflows?limit=100")
except Exception as e:
    print("n8n недоступний:",str(e)[:120]); raise SystemExit
ws=d.get("data",[])
print("воркфлоу всього:",len(ws))
for w in ws:
    try:
        full=w if "nodes" in w else get(B+"workflows/"+str(w.get("id")))
    except Exception:
        full=w
    s=json.dumps(full,ensure_ascii=False)
    hits=[m for m in ["134.209.94.12","8080","nocodb","NocoDB","unitex-os"] if m in s]
    print(" ","УВІМК" if w.get("active") else "вимк ",str(w.get("name"))[:38],"|",",".join(hits) if hits else "-")' 2>&1 | head -28
